def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit difference between two strings."""
    # Simple implementation for now - find first position where chars differ
    min_len = min(len(s_in), len(s_out))
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            return (s_in[i], s_out[i], i)
    # If we reach here, one string is prefix of the other
    if len(s_in) > len(s_out):
        return (s_in[min_len], '', min_len)
    elif len(s_in) < len(s_out):
        return ('', s_out[min_len], min_len)
    return ('', '', -1)

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates based on the change."""
    # For simplicity, let's propose some basic candidates
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Most specific: replace single character at exact position
    candidates = []

    if old_sub and new_sub:
        candidates.append((old_sub, new_sub))

    # Also consider replacing longer substrings if they match
    # Let's check if we can find longer patterns
    if pos >= 0 and pos < len(s_in) and pos < len(s_out):
        # Try to find longer matches
        if pos + 1 <= len(s_in) and pos + 1 <= len(s_out):
            candidates.append((s_in[pos:pos+1], s_out[pos:pos+1]))

    return candidates

